// ---- group F (piece 6a): the FRUSTUM arm (mbUseFrustrumResolver 1) -- the same three-frame run with the policy's
// FrustrumCollisionResolver interpreted whole: GenerateSceneQueries @0x82252540, CalculateFrustumLineTests @0x8220DDE8
// (XMVectorTan @0x821F0788), RequestFrustumLineTests @0x8223FD70, ProcessSceneQueryResults @0x822242F8, against the
// tunables the console's CRT thunks write. Between the halves each frustum box (mTopLeft, mTopRight, mBottomLeft,
// mBottomRight) is answered or left waiting, and the camera can lose its custom near clip. Call id 11 is
//   11 ResolveLineTestNearestUsingDisplacementAndVector  box - policy, test point x4, position (0x10030), vector x4,
//                                                        minimum x4 -- recorder: a box that GOT its package with an
//                                                        intersection moves position.xyz onto the hit and answers 1
struct L1FrustumFrame
{
    u32 mauCamera[16];              // the camera's transform before the frame
    u32 muFieldOfView;              // mfFOV
    u32 muAspectRatio;              // mfAspectRatio
    u32 muSmallNearClip;            // mState's E_FLAG_SMALL_NEAR_CLIP (bit 16)
    u32 muHasCustomNearClip;        // mbHasCustomNearClipDistance before the frame
    u32 muCustomNearClip;           // mfCustomNearClipDistance before the frame
    u32 muClearCustomNearClip;      // mbHasCustomNearClipDistance cleared between the halves
    u32 mauPitch[2];                // GetPitchAboutPointRads's answers, in call order
    u32 mauDeliver[4];              // per frustum box: answered (else left waiting)
    u32 mauIntersection[4];         // ... with mbIntersection
    u32 mauHit[16];                 // ... mPosition, 4 words per box
    u32 mauNormal[16];              // ... mNormal
    u32 mauAfterGenerate[16];       // the console's camera after GenerateSceneQueries
    u32 muAfterGenerateHasCustom;   // ... its mbHasCustomNearClipDistance
    u32 muAfterGenerateCustom;      // ... its mfCustomNearClipDistance
    u32 mauAfterProcess[16];        // ... after ProcessSceneQueryResults
    u32 mauPitchMover[3];           // mPitchMover after (centering rate, speed, value)
    u32 muMaxRadius;                // mfMaxRadius after
    u32 muTrafficResolution;        // mfTrafficCollisionResolution after
    u32 muResetVehicleCollision;    // mbResetVehicleCollision after
    u32 muBoxState;                 // mCarToCamera's state after
    u32 mauFrustumBoxState[4];      // the four frustum boxes' states after
    u32 mauVehicleResolveVector[4]; // the resolver's mVehicleResolveVector after
    u32 muAsserts;                  // asserts fired during the frame
    u32 muFirstCallWord;            // into kau32L1FrustumCallStream
    u32 muCallWords;
};

struct L1FrustumCase
{
    L1Case mBase;                        // as group P; its frames index kaL1FrustumFrames
    u32    mauVehicleResolveVector[4];   // the resolver's mVehicleResolveVector, set after Construct
};

